@startuml

class Location {
  + name : string
}

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + email : string
}

class ItemDescription {
  + description : string
}

class ScheduledPickup {
  + streetAddress : string
  + pickupTime : time
}

class Vehicle {
  + storageSpace : double
}

class PickupRoute {
  + day : date
}

class VolunteerDriver {
  + name : string
}

class Availability {
  + day : date
}

class Article {
  + description : string
  + weight : float
  + dimensions : string
}

class Category {
  + name : string
}

class DistributionCenter {
}

class Employee {
  + name : string
}

class Client {
  + homeAddress : string
}

class Delivery {
}

Location "1" -- "*" Resident
Location "1" -- "*" DistributionCenter
Location "1" -- "*" VolunteerDriver
Location "1" -- "*" Vehicle

Resident "1" -- "*" ScheduledPickup : requests
ScheduledPickup "1" -- "1" ItemDescription
ScheduledPickup "1" -- "1" Vehicle : assigned to
ScheduledPickup "1" -- "1" PickupRoute : part of

PickupRoute "1" -- "1" Vehicle : for
PickupRoute "1" -- "1..*" VolunteerDriver : driven by
VolunteerDriver "1" -- "*" Availability : indicates

Article "*" -- "1" ItemDescription : described by
Article "*" -- "1" Category : assigned to
Article "*" -- "0..1" Article : tagged with

DistributionCenter "1" -- "*" Employee : employs
DistributionCenter "1" -- "*" Article : receives

Client "*" -- "*" Category : needs
Employee "*" -- "*" Client : calls
Employee "*" -- "*" Delivery : arranges
Delivery "*" -- "1" Client : to
Delivery "*" -- "1" Article : of
Delivery "*" -- "1" VolunteerDriver : made by

@enduml

